#include <sys/attr.h>
#include <sys/stat.h>
#include <sys/mount.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
int main(int argc, char **argv) {
 for (int i = 1; i < argc; ++i) {
  int fd = open(argv[i], O_RDONLY | O_CLOEXEC | O_DIRECTORY | O_NOFOLLOW);
  if (fd < 0) {printf("%s open error %d %s\n", argv[i], errno, strerror(errno)); continue;}
  struct attrlist a = {0}; a.bitmapcount=ATTR_BIT_MAP_COUNT; a.commonattr=ATTR_CMN_RETURNED_ATTRS; a.forkattr=ATTR_CMNEXT_RECURSIVE_GENCOUNT;
  uint8_t buf[64] = {0}; int rc = fgetattrlist(fd, &a, buf, sizeof(buf), FSOPT_ATTR_CMN_EXTENDED);
  uint32_t len=0; attribute_set_t set={0}; uint64_t count=0; memcpy(&len,buf,4); memcpy(&set,buf+4,20); memcpy(&count,buf+24,8);
  struct statfs sf={0}; fstatfs(fd,&sf);
  printf("%s fs=%s rc=%d errno=%d len=%u common=%x ext=%x count=%llu\n",argv[i],sf.f_fstypename,rc,errno,len,set.commonattr,set.forkattr,(unsigned long long)count);
  close(fd);
 }
}
